const citas = $input.all().map(i => i.json);
console.log(`[RECORDATORIO] Se generaron ${citas.length} recordatorios para citas programadas para el día de mañana.`);
return citas.map(c => ({
  json: {
    cliente: c.cliente,
    email: c.email,
    telefono: c.phone,
    servicio: c.servicio,
    fecha: c.date,
    hora: c.time,
    mensaje: `Estimado/a ${c.cliente}, te recordamos tu cita de "${c.servicio}" mañana a las ${c.time} en Centro Estético Aura. Por favor llega 10 minutos antes.`
  }
}));
